<?php
require_once 'includes.php';
if($_SERVER['REQUEST_METHOD']==='POST'){try{$a=post('action');if($a==='save'){$id=(int)post('id','0');$d=[(int)post('hostel_id'),post('room_number'),post('room_type'),(int)post('capacity'),(float)post('monthly_fee')];if(!$d[1]||$d[3]<1)throw new Exception('Room number and positive capacity are required.');if($id){if($d[3]<active_count($pdo,$id))throw new Exception('Capacity cannot be lower than current occupancy.');$d[]=$id;$q=$pdo->prepare("UPDATE rooms SET hostel_id=?,room_number=?,room_type=?,capacity=?,monthly_fee=? WHERE room_id=?");$q->execute($d);flash('Room updated.');}else{$q=$pdo->prepare("INSERT INTO rooms(hostel_id,room_number,room_type,capacity,monthly_fee) VALUES(?,?,?,?,?)");$q->execute($d);flash('Room added.');}}elseif($a==='delete'){$q=$pdo->prepare("DELETE FROM rooms WHERE room_id=?");$q->execute([(int)post('id')]);flash('Room deleted.');}}catch(Throwable $e){flash($e->getMessage(),'error');}redirect('rooms.php');}
$hostels=$pdo->query("SELECT hostel_id,hostel_name FROM hostels ORDER BY hostel_name")->fetchAll();
$edit=null;if(isset($_GET['edit'])){$q=$pdo->prepare("SELECT * FROM rooms WHERE room_id=?");$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();}
$rows=$pdo->query("SELECT r.*,h.hostel_name,COUNT(a.allocation_id) occupied FROM rooms r JOIN hostels h ON h.hostel_id=r.hostel_id LEFT JOIN allocations a ON a.room_id=r.room_id AND a.status='Active' GROUP BY r.room_id ORDER BY r.room_id DESC")->fetchAll();
page_header('Room inventory','rooms.php');?>
<div class="toolbar"><span class="muted">Manage room types, capacity and monthly charges.</span><a class="btn" href="#room-form">＋ Add room</a></div>
<section class="form-card" id="room-form"><h3><?=$edit?'Edit room':'Add a room'?></h3><?php if(!$hostels):?><p class="muted">Create a hostel before adding rooms.</p><?php else:?><form method="post"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e($edit['room_id']??'0')?>"><div class="form-grid">
<div class="field"><label>Hostel</label><select name="hostel_id"><?php foreach($hostels as $h):?><option value="<?=$h['hostel_id']?>" <?=((int)($edit['hostel_id']??0)===(int)$h['hostel_id'])?'selected':''?>><?=e($h['hostel_name'])?></option><?php endforeach;?></select></div>
<div class="field"><label>Room number</label><input name="room_number" required value="<?=e($edit['room_number']??'')?>"></div>
<div class="field"><label>Room type</label><select name="room_type"><?php foreach(['Single','Double','Triple','Dormitory'] as $t):?><option <?=$t===($edit['room_type']??'Double')?'selected':''?>><?=$t?></option><?php endforeach;?></select></div>
<div class="field"><label>Capacity</label><input type="number" min="1" max="30" name="capacity" required value="<?=e($edit['capacity']??2)?>"></div>
<div class="field"><label>Monthly fee (₹)</label><input type="number" min="0" step="0.01" name="monthly_fee" value="<?=e($edit['monthly_fee']??4500)?>"></div></div><div class="form-actions"><button class="btn">Save room</button><?php if($edit):?><a class="btn secondary" href="rooms.php">Cancel</a><?php endif;?></div></form><?php endif;?></section>
<h3 class="section-title">Room inventory · <?=count($rows)?></h3><div class="table-wrap"><table><thead><tr><th>ID</th><th>Hostel</th><th>Room</th><th>Type</th><th>Capacity</th><th>Occupied</th><th>Vacant</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):$free=(int)$r['capacity']-(int)$r['occupied'];?><tr><td><?=$r['room_id']?></td><td><?=e($r['hostel_name'])?></td><td><?=e($r['room_number'])?></td><td><?=e($r['room_type'])?></td><td><?=$r['capacity']?></td><td><?=$r['occupied']?></td><td><span class="badge <?=$free===0?'warn':''?>"><?=$free?></span></td><td><div class="actions"><a class="btn small secondary" href="?edit=<?=$r['room_id']?>">Edit</a><form method="post" onsubmit="return confirm('Delete room?')"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['room_id']?>"><button class="btn small danger">Delete</button></form></div></td></tr><?php endforeach;?></tbody></table></div>
<?php page_footer();?>
